messageHandlers.script:
action = ''
try:
	action = str(payload.get('action') or '')
except:
	action = ''
status = ''
cg = ''
area = ''
try:
	status = str(payload.get('status') or '')
except:
	status = ''
try:
	cg = str(payload.get('cg') or '')
except:
	cg = ''
try:
	area = str(payload.get('area') or '')
except:
	area = ''
if action == 'select':
	cur = ''
	try:
		cur = str(self.view.custom.highlightCg or '')
	except:
		cur = ''
	if cg and cur == cg:
		self.view.custom.highlightCg = ''
	else:
		self.view.custom.highlightCg = cg
	# CG focus wins — drop area filter (status left alone; opacity prefers cg)
	self.view.custom.highlightArea = ''
elif action == 'clear':
	# CG + area plant focus — leave status-mix filter alone
	self.view.custom.highlightCg = ''
	self.view.custom.highlightArea = ''
elif action == 'statusToggle':
	cur = ''
	try:
		cur = str(self.view.custom.highlightStatus or '')
	except:
		cur = ''
	if cur == status:
		self.view.custom.highlightStatus = ''
	else:
		self.view.custom.highlightStatus = status
	self.view.custom.highlightCg = ''
	self.view.custom.highlightArea = ''
elif action == 'selectArea':
	cur = ''
	try:
		cur = str(self.view.custom.highlightArea or '')
	except:
		cur = ''
	if area and cur == area:
		self.view.custom.highlightArea = ''
	else:
		self.view.custom.highlightArea = area
	self.view.custom.highlightCg = ''
	self.view.custom.highlightStatus = ''
elif action == 'selectAreaStatus':
	cur_a = ''
	cur_s = ''
	try:
		cur_a = str(self.view.custom.highlightArea or '')
	except:
		cur_a = ''
	try:
		cur_s = str(self.view.custom.highlightStatus or '')
	except:
		cur_s = ''
	if area and status and cur_a == area and cur_s == status:
		self.view.custom.highlightArea = ''
		self.view.custom.highlightStatus = ''
	else:
		self.view.custom.highlightArea = area
		self.view.custom.highlightStatus = status
	self.view.custom.highlightCg = ''

